"""Browser API request/response types."""

from typing import Literal

from pydantic import BaseModel, ConfigDict, Field


class BrowserProxyConfig(BaseModel):
    """How a browser session connects to the internet.

    Omit entirely to use the TinyFish residential proxy in the US, pinned to one exit IP per session.
    """

    model_config = ConfigDict(extra="forbid")

    enabled: bool = True
    """Set False to connect directly, with no proxy. Other fields are then ignored."""
    type: Literal["tinyfish", "custom"] = "tinyfish"
    """"tinyfish" uses the TinyFish residential proxy; "custom" routes through your own proxy."""
    country_code: str | None = None
    """Exit country for the tinyfish proxy (ISO 3166-1 alpha-2). Defaults to US server-side."""
    url: str | None = None
    """Your HTTP or HTTPS proxy URL. Required when type is "custom"."""
    username: str | None = None
    """Username for your custom proxy."""
    password: str | None = None
    """Password for your custom proxy."""


class BrowserSessionCreateParams(BaseModel):
    """Parameters for `browser.sessions.create()`."""

    url: str | None = Field(
        None,
        description="Target URL for the browser session. If omitted, browser starts at about:blank.",
    )
    timeout_seconds: int | None = Field(
        None,
        description="Inactivity timeout in seconds. If omitted or exceeds plan max, the plan max is used.",
    )
    proxy_config: BrowserProxyConfig | None = Field(
        None,
        description="Proxy for the session. If omitted, the TinyFish residential proxy in the US is used.",
    )


class BrowserSession(BaseModel):
    """Response from creating a browser session."""

    session_id: str = Field(..., description="Unique session identifier")
    cdp_url: str = Field(..., description="CDP WebSocket URL for direct browser connection")
    base_url: str = Field(..., description="HTTPS base URL for the browser session")
